-- ==========================================================================
-- W6 / R10 - CONCURRENCY AND VOLATILITY
-- ==========================================================================
-- Nikhil's assigned action item. Deliberately split, because Snowflake already
-- guarantees part of it and the real risk is somewhere else entirely.
--
-- ALREADY GUARANTEED - Using Sequences, verbatim:
--   "All values generated by a sequence are globally unique as long as the
--    sign of the sequence interval does not change. Concurrent queries never
--    observe the same value, and values within a single query are always
--    distinct."
--   So two tables drawing on one sequence CANNOT collide. T4.1-T4.2 confirm
--   the guarantee survives the FUNCTION WRAPPER, which the docs say nothing
--   about - that is the only part still open.
--
-- ALREADY EVIDENCED - R3's T1.4 (see R3_RESULTS.md): 100 rows produced a span
--   of exactly 201-300, so the function ran ONCE PER ROW. T4.3 re-checks that
--   at a larger volume rather than re-deriving it from scratch.
--
-- THE REAL RISK - volatility, not concurrency. Every row passes this function
--   IDENTICAL ARGUMENTS, and IMMUTABLE is an unchecked promise whose breach
--   Snowflake calls "undefined behavior". T4.4-T4.6.
--
-- >>> T4.1, T4.2 and T4.7 MUST RUN IN SEPARATE SESSIONS AT THE SAME TIME. <<<
-- Open three Snowflake worksheets and start them together. Running them one
-- after another proves nothing about concurrency.
--
-- Runtime: about five minutes including the concurrent parts.
-- SCREENSHOT GUIDE: one per numbered test; each ends in a VERDICT column.
-- ==========================================================================

-- EDIT THESE TWO LINES - and use the SAME two in every worksheet.
USE DATABASE LM_POC_DB;
USE SCHEMA POC_SCHEMA;

-- ==========================================================================
-- SETUP - run ONCE, in one worksheet only, before the others start
-- ==========================================================================
CREATE OR REPLACE SEQUENCE w6_shared_seq START 1 INCREMENT 1;

CREATE OR REPLACE TABLE w6_region_map (REGION_NAME VARCHAR(100), REGION_CODE NUMBER(9,0));
INSERT INTO w6_region_map VALUES ('North America', 1), ('EU', 2), ('APAC', 3);

-- The function under test. VOLATILE is explicit, not inherited from the
-- default, and the cast is in the BODY because a SQL UDF's declared NUMBER
-- precision and scale are ignored (R6 / C7, proven in 03_r6_return_datatype).
CREATE OR REPLACE FUNCTION w6_regional_key(region_name VARCHAR)
RETURNS NUMBER(38,0)
VOLATILE
COMMENT = 'VOLATILE IS REQUIRED. IMMUTABLE or MEMOIZABLE would return one key for every row - see T4.4/T4.5.'
AS
$$
    CAST(
        (SELECT m.REGION_CODE FROM w6_region_map m WHERE m.REGION_NAME = region_name)
        * 1000000000000000 + w6_shared_seq.NEXTVAL
    AS NUMBER(38,0))
$$;

CREATE OR REPLACE TABLE w6_keys_employee (K NUMBER(38,0), SRC VARCHAR(50), SESSION_TAG VARCHAR(50));
CREATE OR REPLACE TABLE w6_keys_job      (K NUMBER(38,0), SRC VARCHAR(50), SESSION_TAG VARCHAR(50));
CREATE OR REPLACE TABLE w6_keys_office   (K NUMBER(38,0), SRC VARCHAR(50), SESSION_TAG VARCHAR(50));
CREATE OR REPLACE TABLE w6_keys_multiregion (K NUMBER(38,0), REGION VARCHAR(50));

-- ==========================================================================
-- T4.1  THREE TABLES, ONE FUNCTION, ONE SEQUENCE, ALL AT ONCE
-- ==========================================================================
-- Run ONE of these in each of three worksheets, started together. 20k rows
-- each so the windows genuinely overlap.
-- --------------------------------------------------------------------------

-- >>> WORKSHEET A <<<
INSERT INTO w6_keys_employee (K, SRC, SESSION_TAG)
SELECT w6_regional_key('North America'), 'EMPLOYEE', CURRENT_SESSION()
FROM TABLE(GENERATOR(ROWCOUNT => 20000));

-- >>> WORKSHEET B <<<
INSERT INTO w6_keys_job (K, SRC, SESSION_TAG)
SELECT w6_regional_key('North America'), 'JOB', CURRENT_SESSION()
FROM TABLE(GENERATOR(ROWCOUNT => 20000));

-- >>> WORKSHEET C <<<
INSERT INTO w6_keys_office (K, SRC, SESSION_TAG)
SELECT w6_regional_key('North America'), 'OFFICE', CURRENT_SESSION()
FROM TABLE(GENERATOR(ROWCOUNT => 20000));

-- ==========================================================================
-- T4.2  THE ASSERTION - no key issued twice, across all three tables
-- ==========================================================================
WITH all_keys AS (
    SELECT K, SRC, SESSION_TAG FROM w6_keys_employee
    UNION ALL SELECT K, SRC, SESSION_TAG FROM w6_keys_job
    UNION ALL SELECT K, SRC, SESSION_TAG FROM w6_keys_office
)
SELECT COUNT(*)                     AS total_keys,
       COUNT(DISTINCT K)            AS distinct_keys,
       COUNT(*) - COUNT(DISTINCT K) AS duplicates,
       COUNT(DISTINCT SESSION_TAG)  AS sessions_involved,
       CASE WHEN COUNT(DISTINCT SESSION_TAG) < 3
            THEN 'INVALID - the three inserts did NOT run in separate sessions, redo'
            WHEN COUNT(*) = COUNT(DISTINCT K)
            THEN 'PASS - R10 holds through the wrapper'
            ELSE 'FAIL - key reuse across concurrent loads' END AS verdict
FROM all_keys;
-- EXPECT: 60000 / 60000 / 0 / 3 / PASS.
-- sessions_involved < 3 invalidates the run - it was not concurrent.
-- ------------------------------------------------------------------ PASS/FAIL

-- T4.2b  If T4.2 failed, where did the duplicates come from?
WITH all_keys AS (
    SELECT K, SRC FROM w6_keys_employee
    UNION ALL SELECT K, SRC FROM w6_keys_job
    UNION ALL SELECT K, SRC FROM w6_keys_office
)
SELECT K, COUNT(*) AS times_issued, LISTAGG(DISTINCT SRC, ', ') AS issued_to
FROM all_keys GROUP BY K HAVING COUNT(*) > 1
ORDER BY times_issued DESC LIMIT 20;
-- EXPECT: zero rows. ------------------------------------------------ PASS/FAIL

-- ==========================================================================
-- T4.3  INVOCATION COUNT AT VOLUME
-- ==========================================================================
-- R3's T1.4 already showed one call per row on a 100-row plan. This re-checks
-- it at 60k across three concurrent sessions, where the plan is different.
--
-- MEASURED FROM INFORMATION_SCHEMA, NOT A BARE NEXTVAL. R3's T1.5 tried a bare
-- SELECT seq.NEXTVAL and got a misleading answer, because direct and UDF calls
-- draw from different reserved ranges under NOORDER. NEXT_VALUE reads metadata
-- and consumes nothing. Do not substitute a bare NEXTVAL here.
-- --------------------------------------------------------------------------
WITH issued AS (
    SELECT COUNT(*) AS rows_keyed FROM (
        SELECT K FROM w6_keys_employee
        UNION ALL SELECT K FROM w6_keys_job
        UNION ALL SELECT K FROM w6_keys_office)
),
seq AS (
    SELECT TO_NUMBER(NEXT_VALUE) AS next_value, ORDERED
    FROM INFORMATION_SCHEMA.SEQUENCES
    WHERE SEQUENCE_SCHEMA = CURRENT_SCHEMA() AND SEQUENCE_NAME = 'W6_SHARED_SEQ'
)
SELECT issued.rows_keyed,
       seq.next_value                              AS sequence_next_value,
       seq.next_value - 1 - issued.rows_keyed      AS values_beyond_rows,
       ROUND((seq.next_value - 1) / issued.rows_keyed, 3) AS values_per_row,
       seq.ORDERED                                 AS sequence_ordered,
       CASE WHEN (seq.next_value - 1) / issued.rows_keyed < 1.05
            THEN 'PASS - about one value per row'
            WHEN (seq.next_value - 1) / issued.rows_keyed < 2.5
            THEN 'RECORD - some over-consumption, likely range reservation'
            ELSE 'INVESTIGATE - consumption far outruns rows' END AS verdict
FROM issued, seq;
-- EXPECT: values_per_row at or just above 1.0.
-- NOTE: range reservation under NOORDER can inflate this without any extra
-- invocation, so a modest excess is NOT evidence of double-calling. A multiple
-- (2x, 3x) is. Record the number either way. ORDERED should read NO.
-- ------------------------------------------------------------------ RECORD

-- ==========================================================================
-- T4.4  THE SILENT KILLER - IMMUTABLE
-- ==========================================================================
-- Every row passes identical arguments, so IMMUTABLE lets Snowflake reuse one
-- result. CREATE FUNCTION: "This guarantee is not checked. Specifying
-- IMMUTABLE for a UDF that returns different values for the same input will
-- result in undefined behavior."
--
-- Run this to SEE the failure, so the prohibition is evidenced, not asserted.
-- NEVER SHIP THIS FORM.
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION w6_regional_key_immutable(region_name VARCHAR)
RETURNS NUMBER(38,0)
IMMUTABLE                      -- DELIBERATELY WRONG. Negative test.
AS
$$
    CAST(
        (SELECT m.REGION_CODE FROM w6_region_map m WHERE m.REGION_NAME = region_name)
        * 1000000000000000 + w6_shared_seq.NEXTVAL
    AS NUMBER(38,0))
$$;

WITH probe AS (
    SELECT w6_regional_key_immutable('North America') AS k
    FROM TABLE(GENERATOR(ROWCOUNT => 1000))
)
SELECT COUNT(*) AS rows_generated, COUNT(DISTINCT k) AS distinct_keys,
       CASE WHEN COUNT(DISTINCT k) = 1
            THEN 'CONFIRMED - one key for 1000 rows. Never use IMMUTABLE.'
            WHEN COUNT(DISTINCT k) < COUNT(*)
            THEN 'PARTIAL FOLDING - still unusable'
            ELSE 'no folding on THIS run - see the note below' END AS verdict
FROM probe;
-- EXPECT: distinct_keys = 1, or well below 1000.
-- IF distinct_keys = 1000: folding did not happen on this run. That is NOT a
-- clean bill of health. "Undefined behavior" means it may fold on a larger
-- warehouse, a different plan, or a future release. The prohibition rests on
-- the documentation, not on this result. ---------------------------- RECORD

-- ==========================================================================
-- T4.5  MEMOIZABLE - the same failure by another route
-- ==========================================================================
-- The SQL handler syntax accepts [ MEMOIZABLE ] alongside the volatility
-- keyword. Its own documentation page 404s, so this is characterised here.
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION w6_regional_key_memo(region_name VARCHAR)
RETURNS NUMBER(38,0)
MEMOIZABLE                     -- DELIBERATELY WRONG. Negative test.
AS
$$
    CAST(
        (SELECT m.REGION_CODE FROM w6_region_map m WHERE m.REGION_NAME = region_name)
        * 1000000000000000 + w6_shared_seq.NEXTVAL
    AS NUMBER(38,0))
$$;
-- EXPECT: either refused at CREATE, or it creates and folds like T4.4.
-- RECORD WHICH - including the error text if it is refused. --------- RECORD

WITH probe AS (
    SELECT w6_regional_key_memo('North America') AS k FROM TABLE(GENERATOR(ROWCOUNT => 1000))
)
SELECT COUNT(*) AS rows_generated, COUNT(DISTINCT k) AS distinct_keys,
       CASE WHEN COUNT(DISTINCT k) < COUNT(*) THEN 'FOLDED - never use MEMOIZABLE'
            ELSE 'no folding on this run - prohibition still stands' END AS verdict
FROM probe;
-- ------------------------------------------------------------------ RECORD

-- ==========================================================================
-- T4.6  CONFIRM THE SHIPPING FUNCTION DECLARES WHAT WE THINK
-- ==========================================================================
-- Guards against someone "optimising" it later.
-- --------------------------------------------------------------------------
SELECT FUNCTION_NAME,
       VOLATILITY,
       IS_MEMOIZABLE,
       CASE WHEN FUNCTION_NAME = 'W6_REGIONAL_KEY'
             AND VOLATILITY = 'VOLATILE' AND IS_MEMOIZABLE = 'NO'
            THEN 'PASS - shipping function is VOLATILE and not memoizable'
            WHEN FUNCTION_NAME = 'W6_REGIONAL_KEY'
            THEN 'FAIL - the shipping function is misdeclared'
            ELSE 'negative-test function, expected to be wrong' END AS verdict
FROM INFORMATION_SCHEMA.FUNCTIONS
WHERE FUNCTION_SCHEMA = CURRENT_SCHEMA()
  AND FUNCTION_NAME ILIKE 'W6_REGIONAL_KEY%'
ORDER BY FUNCTION_NAME;
-- EXPECT: three rows. W6_REGIONAL_KEY -> VOLATILE / NO / PASS.
-- The two negative-test functions should show IMMUTABLE and memoizable YES,
-- which is the point of them. This query is the one to re-run in CI or a
-- release check, since it catches a later "optimisation" in one line.
-- ------------------------------------------------------------------ PASS/FAIL

-- ==========================================================================
-- T4.7  CROSS-REGION UNIQUENESS UNDER CONCURRENCY
-- ==========================================================================
-- R12 rather than R10, but this is the only place all three regions run at
-- once. Again: THREE SEPARATE WORKSHEETS, STARTED TOGETHER.
-- --------------------------------------------------------------------------

-- >>> WORKSHEET A <<<
INSERT INTO w6_keys_multiregion
SELECT w6_regional_key('North America'), 'North America' FROM TABLE(GENERATOR(ROWCOUNT => 10000));
-- >>> WORKSHEET B <<<
INSERT INTO w6_keys_multiregion
SELECT w6_regional_key('EU'), 'EU' FROM TABLE(GENERATOR(ROWCOUNT => 10000));
-- >>> WORKSHEET C <<<
INSERT INTO w6_keys_multiregion
SELECT w6_regional_key('APAC'), 'APAC' FROM TABLE(GENERATOR(ROWCOUNT => 10000));

SELECT COUNT(*) AS total, COUNT(DISTINCT K) AS distinct_keys,
       COUNT(*) - COUNT(DISTINCT K) AS duplicates,
       COUNT(DISTINCT REGION) AS regions,
       CASE WHEN COUNT(*) = COUNT(DISTINCT K) THEN 'PASS' ELSE 'FAIL' END AS verdict
FROM w6_keys_multiregion;
-- EXPECT: 30000 / 30000 / 0 / 3 / PASS. ----------------------------- PASS/FAIL

-- T4.7b  Does every key decode back to the region that issued it? (R13)
SELECT k.REGION,
       COUNT(*) AS keys_issued,
       SUM(CASE WHEN FLOOR(K / 1000000000000000) = m.REGION_CODE THEN 1 ELSE 0 END) AS decode_correct,
       CASE WHEN COUNT(*) = SUM(CASE WHEN FLOOR(K / 1000000000000000) = m.REGION_CODE THEN 1 ELSE 0 END)
            THEN 'PASS' ELSE 'FAIL' END AS verdict
FROM w6_keys_multiregion k
JOIN w6_region_map m ON m.REGION_NAME = k.REGION
GROUP BY k.REGION ORDER BY k.REGION;
-- EXPECT: decode_correct = keys_issued for all three regions. ------- PASS/FAIL

-- ==========================================================================
-- T4.8  INTERVAL SIGN - a constraint to record, not a test to run
-- ==========================================================================
-- "Changing the sequence interval from positive to negative, or vice versa,
-- may result in duplicates." Once keys are issued, INCREMENT must NEVER flip.
-- DO NOT RUN:   ALTER SEQUENCE w6_shared_seq SET INCREMENT = -1;
--
-- Likewise, do NOT set ORDER on these sequences later to tidy the keys. R3
-- showed they are NOORDER, which "can improve performance when multiple INSERT
-- operations are performed concurrently" - exactly this workload - and which
-- weakens ordering, never uniqueness.
-- ------------------------------------------------------------- CONSTRAINT ONLY

-- --------------------------------------------------------------------------
-- TEARDOWN
--
-- >>> DO NOT RUN THIS UNTIL EVERY WORKSHEET HAS FINISHED. <<<
-- If you run this file straight through in a single worksheet, T4.1 and T4.7
-- execute one after another rather than together, and T4.2's verdict will say
-- INVALID (sessions_involved < 3). That is the test catching a non-concurrent
-- run, not a failure of the design - redo those parts in parallel worksheets.
-- --------------------------------------------------------------------------
DROP FUNCTION IF EXISTS w6_regional_key(VARCHAR);
DROP FUNCTION IF EXISTS w6_regional_key_immutable(VARCHAR);
DROP FUNCTION IF EXISTS w6_regional_key_memo(VARCHAR);
DROP TABLE    IF EXISTS w6_keys_employee;
DROP TABLE    IF EXISTS w6_keys_job;
DROP TABLE    IF EXISTS w6_keys_office;
DROP TABLE    IF EXISTS w6_keys_multiregion;
DROP TABLE    IF EXISTS w6_region_map;
DROP SEQUENCE IF EXISTS w6_shared_seq;

-- ==========================================================================
-- WHAT "R10 VALIDATED" MEANS WHEN THIS PACK IS DONE
-- ==========================================================================
--  T4.2   60k keys from 3 concurrent sessions, 0 duplicates, 3 sessions seen
--  T4.3   consumption proportional to rows; values_per_row recorded
--  T4.4   IMMUTABLE folding demonstrated, or documented as undefined anyway
--  T4.5   MEMOIZABLE behaviour recorded (refused, or folds)
--  T4.6   shipping function proven VOLATILE and not memoizable
--  T4.7   30k keys across 3 concurrent regions, 0 duplicates
--  T4.7b  every key decodes to its issuing region
--  T4.8   interval-sign and NOORDER constraints in the build standard
--
-- Anything short of this is a partial answer to the action item.
-- ==========================================================================
